BEGIN TRANSACTION READ ONLY;
WITH expected AS(SELECT * FROM jsonb_to_recordset('[{"name":"bedos_project_actor","hash":"24ac0a35598f2b9c3fec98fcbda3d49e","backend":false,"definer":true},{"name":"bedos_project_input","hash":"762681e49d91a84944490ea5100ca930","backend":false,"definer":false},{"name":"bedos_project_lock","hash":"4f156032229d5a24f295617bcd9bacd7","backend":false,"definer":true},{"name":"bedos_project_projection","hash":"9fdeb30d3aa0575e5f2fa71be234c7d7","backend":false,"definer":false},{"name":"bedos_project_read","hash":"69845a5b3f71a37ee01014b810bdd2ff","backend":true,"definer":true},{"name":"bedos_project_mutate","hash":"4acfbdbac25c3d4dbb174a9f8a2c9873","backend":true,"definer":true},{"name":"bedos_project_media","hash":"941a3db0b6430b215af8cf0e71151d5f","backend":true,"definer":true}]'::jsonb) e(name text,hash text,backend boolean,definer boolean)),functions AS(SELECT e.name,p.oid,md5(regexp_replace(p.prosrc,'\s','','g'))=e.hash source_matches,p.prosecdef=e.definer definer_matches,pg_get_userbyid(p.proowner)='postgres' owner_matches,coalesce(p.proconfig @> ARRAY['search_path=""'],false) path_matches,NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE') AND has_function_privilege('service_role',p.oid,'EXECUTE')=e.backend acl_matches FROM expected e LEFT JOIN pg_proc p ON p.pronamespace='public'::regnamespace AND p.proname=e.name), checks(name,pass) AS(
SELECT 'seven functions exact source owner paths security and ACLs',count(*)=7 AND bool_and(oid IS NOT NULL AND source_matches AND definer_matches AND owner_matches AND path_matches AND acl_matches) FROM functions
UNION ALL SELECT 'migration registry exact phase',(SELECT max(version) FROM supabase_migrations.schema_migrations)='20261102030000' AND (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version IN('20261102030000','20261102040000'))=1
