UNION ALL SELECT 'no content or operation fixtures',(SELECT count(*) FROM public.projects)+(SELECT count(*) FROM public.project_stages)+(SELECT count(*) FROM public.project_images)+(SELECT count(*) FROM public.project_categories)+(SELECT count(*) FROM public.project_services)+(SELECT count(*) FROM public.project_media_operations)+(SELECT count(*) FROM storage.objects WHERE bucket_id='project-images')=0
) SELECT jsonb_build_object('phase',1,'all_passed',bool_and(pass),'checks',jsonb_object_agg(name,pass),'functions',(SELECT jsonb_agg(to_jsonb(f) ORDER BY name) FROM functions f)) evidence FROM checks;COMMIT;